\title{Structural Base Cases for Seymour's Second Neighborhood Conjecture}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
Seymour's Second Neighborhood Conjecture (SSNC) asserts that every finite
oriented graph contains a vertex whose second out-neighborhood is at least as
large as its first out-neighborhood. Despite its elementary statement, the
conjecture has remained open since the 1990s, with unconditional progress
confined to structured families (tournaments, transitive digraphs) and to
regimes of bounded minimum out-degree. We isolate and rigorously establish the
clean structural core of the minimum-out-degree program. We prove that every
finite oriented graph whose minimum out-degree is at most one contains a Seymour
vertex, so any minimal counterexample has minimum out-degree at least two. We
prove that every finite nonempty transitive oriented graph contains a Seymour
vertex, realized by a sink. We prove that in a functional oriented graph --- one
in which every vertex has out-degree exactly one --- \emph{every} vertex is a
Seymour vertex. Finally, we give a sharp two-vertex example demonstrating that
the oriented (digon-free) hypothesis cannot be dropped.
\end{abstract}

\maketitle

\section{Introduction}

Let $D = (V, A)$ be a finite directed graph. For a vertex $v$, the
\emph{first out-neighborhood} $\Np(v)$ is the set of vertices $w$ with an arc
$v \adj w$, and the \emph{second out-neighborhood} $\Npp(v)$ is the set of
vertices at directed distance exactly two: those reachable by a directed walk of
length two that are neither equal to $v$ nor already in $\Np(v)$.

An \emph{oriented graph} is a directed graph with no loops and no \emph{digons}
(pairs of opposite arcs $v \adj w$ and $w \adj v$). Equivalently, its adjacency
relation is \emph{asymmetric}: $v \adj w$ implies $w \not\adj v$. Asymmetry
automatically rules out loops.

\begin{conjecture}[Seymour, c.\ 1990]
Every finite oriented graph contains a vertex $v$ with
$|\Npp(v)| \ge |\Np(v)|$.
\end{conjecture}

Such a vertex is called a \emph{Seymour vertex}. Fisher (1996), building on Dean
and Latka (1995), proved SSNC for all tournaments; Havet and Thomass\'e (2000)
gave a combinatorial proof; and a line of work culminating in Ai, Gerke, Gutin,
Wang, Ye, and Zhou (2024) established the conjecture for oriented graphs of
minimum out-degree at most $7$. The full conjecture remains open. This paper
formalizes the structural bedrock of the minimum-out-degree program.

\section{Definitions}

Fix a finite vertex set $V$ and an asymmetric adjacency relation, writing
$v \adj w$ for adjacency. Asymmetry is the hypothesis
\[
\forall a, b \in V,\quad a \adj b \implies \neg\,(b \adj a).
\]

\begin{definition}[Out-neighborhood]
$\Np(v) = \{\, w \in V : v \adj w \,\}$, and $\dplus(v) = |\Np(v)|$ is the
\emph{out-degree} of $v$.
\end{definition}

\begin{definition}[Second out-neighborhood]
\[
\Npp(v) = \{\, w \in V : w \ne v,\ w \notin \Np(v),\ \exists x\ (v \adj x \wedge x \adj w) \,\}.
\]
\end{definition}

\begin{definition}[Seymour vertex]
A vertex $v$ is a \emph{Seymour vertex} if $\dplus(v) \le |\Npp(v)|$.
\end{definition}

\begin{definition}[Sink]
A vertex $v$ is a \emph{sink} if $\Np(v) = \varnothing$, i.e.\ $\dplus(v) = 0$.
\end{definition}

\section{Elementary lemmas}

\begin{lemma}[Irreflexivity]\label{lem:irrefl}
If the adjacency relation is asymmetric, then $v \not\adj v$ for every $v$.
\end{lemma}
\begin{proof}
If $v \adj v$, asymmetry with $a = b = v$ gives $\neg(v \adj v)$, a
contradiction.
\end{proof}

\begin{lemma}[Sinks are Seymour vertices]\label{lem:sink}
If $\Np(v) = \varnothing$ then $v$ is a Seymour vertex.
\end{lemma}
\begin{proof}
Then $\dplus(v) = 0 \le |\Npp(v)|$ trivially.
\end{proof}

\section{The base case of the minimum-out-degree program}

\begin{theorem}\label{thm:base}
Let $D$ be a finite nonempty oriented graph. Suppose there is a vertex $u$ of
minimum out-degree with $\dplus(u) \le 1$; that is, $\dplus(u) \le \dplus(v)$
for all $v$, and $\dplus(u) \le 1$. Then $D$ has a Seymour vertex.
\end{theorem}
\begin{proof}
If $\dplus(u) = 0$ then $u$ is a sink and we are done by Lemma~\ref{lem:sink}.

Otherwise $\dplus(u) = 1$, so $\Np(u) = \{w\}$ for a unique $w$, and $u \adj w$.
Since $u$ has minimum out-degree, $\dplus(w) \ge 1$, so there exists $x$ with
$w \adj x$. We show $x \in \Npp(u)$. The walk $u \adj w \adj x$ has length two.
If $x = u$ then $w \adj u$ while $u \adj w$, contradicting asymmetry; so
$x \ne u$. If $x = w$ then $w \adj w$, contradicting Lemma~\ref{lem:irrefl}; so
$x \notin \Np(u) = \{w\}$. Hence $x \in \Npp(u)$, giving
$|\Npp(u)| \ge 1 = \dplus(u)$, so $u$ is a Seymour vertex.
\end{proof}

\begin{corollary}
A minimal counterexample to SSNC has minimum out-degree at least two.
\end{corollary}

\section{Transitive oriented graphs}

An oriented graph is \emph{transitive} if $a \adj b$ and $b \adj c$ imply
$a \adj c$. A transitive asymmetric relation is precisely a strict partial
order.

\begin{lemma}[Existence of a sink]\label{lem:sinkexists}
Every finite nonempty transitive oriented graph has a sink.
\end{lemma}
\begin{proof}
The reversed relation $r(a,b) := (b \adj a)$ is transitive (from transitivity of
$\adj$) and irreflexive (Lemma~\ref{lem:irrefl}), hence well-founded on the
finite set $V$. A minimal element $m$ satisfies $\neg\,r(a,m)$ for all $a$, i.e.\
$m \not\adj a$ for all $a$, so $\Np(m) = \varnothing$.
\end{proof}

\begin{theorem}\label{thm:trans}
Every finite nonempty transitive oriented graph has a Seymour vertex.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:sinkexists} it has a sink $m$, which is a Seymour vertex by
Lemma~\ref{lem:sink}.
\end{proof}

\begin{remark}
Transitivity forces the second neighborhood of a \emph{maximal} vertex $m$ to be
empty: any walk $m \adj y \adj z$ yields $m \adj z$, so $z \in \Np(m)$ and thus
$z \notin \Npp(m)$. Transitive graphs are the regime of maximal second-neighborhood
collapse.
\end{remark}

\section{Functional oriented graphs}

A \emph{functional} oriented graph is one in which every vertex has out-degree
exactly one; its arc set is the graph of a fixed-point-free, $2$-cycle-free
function $f : V \to V$.

\begin{theorem}\label{thm:func}
In a finite functional oriented graph, every vertex is a Seymour vertex.
\end{theorem}
\begin{proof}
Fix $v$; write $\Np(v) = \{w\}$. Since $\dplus(w) = 1$, there is $x$ with
$w \adj x$. Asymmetry gives $x \ne v$ and Lemma~\ref{lem:irrefl} gives
$x \ne w$, so $x \notin \Np(v) = \{w\}$; the walk $v \adj w \adj x$ places
$x \in \Npp(v)$. Hence $|\Npp(v)| \ge 1 = \dplus(v)$.
\end{proof}

\section{Necessity of the oriented hypothesis}

\begin{theorem}\label{thm:digon}
There exists a finite symmetric digraph of constant out-degree one with no
Seymour vertex: take $V = \{a, b\}$ with $a \adj b$ and $b \adj a$.
\end{theorem}
\begin{proof}
Each vertex has out-degree one. The only walk of length two from $a$ is
$a \adj b \adj a$, returning to $a$, and $a \notin \Npp(a)$ by definition; so
$\Npp(a) = \varnothing$ and symmetrically $\Npp(b) = \varnothing$. Thus
$|\Npp(a)| = 0 < 1 = \dplus(a)$ and likewise for $b$: neither is a Seymour
vertex.
\end{proof}

Consequently any proof of SSNC must use asymmetry essentially, and SSNC is
genuinely a statement about oriented graphs.

\section{Algorithms}

\textbf{Algorithm A (detection).} Given the adjacency matrix, compute $\Np(v)$
and $\Npp(v)$ for each $v$ via Boolean matrix reachability and report any vertex
with $|\Npp(v)| \ge |\Np(v)|$; this runs in $O(n^3)$ time.

\textbf{Algorithm B (exhaustive small-case check).} Enumerate all
$3^{\binom{n}{2}}$ oriented graphs on $n$ labeled vertices and confirm each has a
Seymour vertex; feasible for small $n$.

\section{Discussion and future work}

The base cases delineate where the difficulty concentrates: out-degrees zero and
one, transitivity, and functionality are all trivial, so the genuine content of
SSNC lives at minimum out-degree two and above. The immediate target is proving
SSNC for minimum out-degree two via a discharging argument on the bounded
configuration around a minimum-degree vertex. Further questions concern the
number of Seymour vertices (controlled by distance from transitivity) and a
weighted, martingale-flavored reformulation over probability distributions on
$V$.

