from itertools import product
from typing import List, Set

Graph = List[List[bool]]

def out_neighborhood(adj: Graph, v: int) -> Set[int]:
    return {w for w in range(len(adj)) if adj[v][w]}

def second_out_neighborhood(adj: Graph, v: int) -> Set[int]:
    n = len(adj)
    first = out_neighborhood(adj, v)
    reach2: Set[int] = set()
    for x in first:
        for w in range(n):
            if adj[x][w]:
                reach2.add(w)
    return {w for w in reach2 if w != v and w not in first}

def seymour_vertices(adj: Graph) -> List[int]:
    return [v for v in range(len(adj))
            if len(out_neighborhood(adj, v)) <= len(second_out_neighborhood(adj, v))]

if __name__ == "__main__":
    # transitive chain on 4 vertices: 4 (the sink) is the Seymour vertex
    g = [[i < j for j in range(4)] for i in range(4)]
    print("transitive chain Seymour vertices:", seymour_vertices(g))

from itertools import product
from typing import List, Set, Tuple

Graph = List[List[bool]]

def seymour_vertices(adj: Graph) -> List[int]:
    n = len(adj)
    out = []
    for v in range(n):
        first = {w for w in range(n) if adj[v][w]}
        reach2 = set()
        for x in first:
            for w in range(n):
                if adj[x][w]:
                    reach2.add(w)
        second = {w for w in reach2 if w != v and w not in first}
        if len(first) <= len(second):
            out.append(v)
    return out

def all_oriented_graphs(n: int):
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    for choice in product((0, 1, 2), repeat=len(pairs)):
        arcs: Set[Tuple[int, int]] = set()
        for (i, j), c in zip(pairs, choice):
            if c == 1: arcs.add((i, j))
            elif c == 2: arcs.add((j, i))
        yield [[(u, v) in arcs for v in range(n)] for u in range(n)]

if __name__ == "__main__":
    for n in range(1, 5):
        total = ok = 0
        for g in all_oriented_graphs(n):
            total += 1
            if seymour_vertices(g): ok += 1
        print(f"n={n}: {ok}/{total} oriented graphs have a Seymour vertex")

from typing import List, Set

Graph = List[List[bool]]

def check_all_seymour_in_functional(n: int) -> bool:
    # directed n-cycle: 0->1->...->n-1->0, every out-degree is 1
    adj: Graph = [[(j == (i + 1) % n) for j in range(n)] for i in range(n)]
    for v in range(n):
        first = {w for w in range(n) if adj[v][w]}
        reach2 = set()
        for x in first:
            for w in range(n):
                if adj[x][w]: reach2.add(w)
        second = {w for w in reach2 if w != v and w not in first}
        if not len(first) <= len(second):
            return False
    return True

if __name__ == "__main__":
    for n in range(3, 9):
        print(f"functional {n}-cycle: every vertex Seymour =",
              check_all_seymour_in_functional(n))

